def minimumSwap(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1
    if (s1.count('x') + s2.count('x')) % 2 != 0:
        return -1
    count_xy = count_yx = 0
    for c1, c2 in zip(s1, s2):
        if c1 < c2:
            count_xy += 1
        elif c1 > c2:
            count_yx += 1
    return (count_xy + count_yx) // 2 + count_xy % 2
